// Складаємо steps/state за contracts/setup-result.schema.json. Ітерація 1 нічого не створює,
// тому outcome тут може бути лише ok | missing | skipped — created/failed зʼявляться з ітерацією 2.
const CANON_WEBHOOKS = [
  { events: ['reply'], url: 'https://n8n.coldunicorn.com/webhook/aimfox-classifier' },
  { events: ['lead_label_added'], url: 'https://n8n.coldunicorn.com/webhook/preMQL-Aimfox' },
];
const CANON_LABELS = ['preMQL', 'MQL'];

const input = $('Start').first().json;
const client = $('Resolve Client').first().json ?? {};
const resolution = $('Resolve Workspace').first().json ?? {};
const tokensRaw = $('List Tokens').first().json ?? {};
const hooksRaw = $('List Webhooks').first().json ?? {};
const labelsRaw = $('List Labels').first().json ?? {};

const errored = (raw) => Boolean(raw?.error) || raw?.status === 'fail';

// Ідентичність вебхука — events + url, НІКОЛИ не назва. Вебхук GIC зветься "Manual Tag", б'є в
// правильний URL на правильну подію, і звірка за назвою створила б другий на ту саму подію.
const hookKey = (events, url) => `${[...(events ?? [])].map(String).sort().join('+')} ${String(url ?? '').trim()}`;

const step = (outcome, present = [], missing = [], error = null) => ({
  outcome, present, ...(missing.length ? { missing } : {}), ...(error ? { error } : {}),
});

const storedKey = Boolean(client.api_key);
const vendorTokens = Array.isArray(tokensRaw.tokens) ? tokensRaw.tokens
  : Array.isArray(tokensRaw.data) ? tokensRaw.data : [];

let key;
if (storedKey) key = step('ok', ['client_sequencers.api_key']);
else if (errored(tokensRaw)) key = step('missing', [], ['api_key'], 'could not read vendor tokens');
else if (vendorTokens.length) key = step('missing', [`vendor holds ${vendorTokens.length} token(s)`], ['api_key']);
else key = step('missing', [], ['api_key']);

let webhooks, labels;
if (!storedKey || errored(hooksRaw)) {
  webhooks = step('skipped', [], [], storedKey ? 'vendor call failed' : 'no workspace key stored yet');
} else {
  const present = (hooksRaw.webhooks ?? []).map((w) => hookKey(w.events, w.url));
  const missing = CANON_WEBHOOKS.filter((c) => !present.includes(hookKey(c.events, c.url)))
    .map((c) => hookKey(c.events, c.url));
  webhooks = step(missing.length ? 'missing' : 'ok', present, missing);
}

if (!storedKey || errored(labelsRaw)) {
  labels = step('skipped', [], [], storedKey ? 'vendor call failed' : 'no workspace key stored yet');
} else {
  const present = (labelsRaw.labels ?? []).map((l) => String(l?.name ?? ''));
  const missing = CANON_LABELS.filter((n) => !present.includes(n));
  labels = step(missing.length ? 'missing' : 'ok', present, missing);
}

const steps = { key, webhooks, labels, campaigns: step('skipped', [], [], 'not implemented in the read-only iteration') };

const decided = [key, webhooks, labels];
const state = decided.every((s) => s.outcome === 'ok') ? 'configured'
  : decided.every((s) => s.outcome !== 'ok') ? 'missing'
  : 'partial';

return [{ json: {
  client_id: input.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'aimfox',
  dry_run: true,
  read_only_iteration: true,
  resolved: resolution.resolved ?? null,
  state,
  steps,
} }];

const input = $('Start').first().json;
const client = $('Resolve Client').first().json ?? {};
const resolution = $('Resolve Workspace').first().json ?? {};

// Неіснуючий клієнт — помилка того, хто викликав, а не стан провіженінгу. Але сказати про це
// треба вголос: мовчазний обрив із status=success — це те, як зникли ліди Audytel.
const state = resolution.client_missing ? 'client_not_found' : 'needs_selection';
const reason = resolution.client_missing ? 'no such client, or it has no enabled aimfox connector'
  : resolution.ambiguous ? 'more than one workspace matches the client name'
  : resolution.list_error ? `could not list workspaces: ${resolution.list_error}`
  : 'no workspace matches the client name';

return [{ json: {
  client_id: input.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'aimfox',
  dry_run: true,
  read_only_iteration: true,
  resolved: null,
  state,
  reason,
  candidates: resolution.candidates ?? [],
  steps: {
    key: { outcome: 'skipped' }, webhooks: { outcome: 'skipped' },
    labels: { outcome: 'skipped' }, campaigns: { outcome: 'skipped' },
  },
} }];

// Порядок резолву: явний id → уже записаний за клієнтом → ТОЧНИЙ збіг назви → кандидати.
//
// Крок "записаний" критичний. Виміряно 2026-08-07: назва клієнта збігається з назвою воркспейсу
// лише в 4 випадках із 9 ("Bent Iron PL" vs "Bent Iron", "FortumEnergia" vs "Fortum",
// "ColdUnicorn PL" vs "Łukasz Kot"). Для вже заведеного клієнта воркспейс відомий з бази, і
// шукати за назвою не треба взагалі — інакше Bent Iron PL іде в needs_selection на рівному місці.
//
// Неоднозначність ніколи не вирішується здогадкою — інваріант 2. Саме здогадка призвела до того,
// що воркспейс GIC опинився на клієнті Prac.Finansowa.
const input = $('Start').first().json;
const client = $('Resolve Client').first().json ?? {};
const listRaw = $('List Workspaces').first().json ?? {};
const claimedRaw = $('Read Claimed').first().json ?? {};

const list = Array.isArray(listRaw.workspaces) ? listRaw.workspaces
  : Array.isArray(listRaw.data) ? listRaw.data
  : [];
const idOf = (w) => String(w?.id ?? w?.workspace_id ?? '').trim();
const nameOf = (w) => String(w?.name ?? '').trim();

const claimed = new Set((claimedRaw.claimed ?? []).map(String));
const listError = listRaw.error ? String(listRaw.error?.message ?? listRaw.error) : null;
const base = { candidates: [], list_error: listError, workspaces_seen: list.length };

// Resolve Client має alwaysOutputData, тож порожній клієнт приходить як {} замість того, щоб
// тихо обірвати ланцюжок. Кажемо про це вголос — мовчазний успіх гірший за помилку.
if (!String(client.client_name ?? '').trim()) {
  return [{ json: { ...base, resolved: null, client_missing: true } }];
}

const nameFor = (id) => nameOf(list.find((w) => idOf(w) === id)) || null;

const explicit = String(input.workspace_id ?? '').trim();
if (explicit) {
  return [{ json: { ...base, resolved: { workspace_id: explicit, name: nameFor(explicit), matched_by: 'explicit' } } }];
}

const stored = String(client.stored_workspace_id ?? '').trim();
if (stored) {
  return [{ json: { ...base, resolved: { workspace_id: stored, name: nameFor(stored), matched_by: 'stored' } } }];
}

const target = String(client.client_name).trim().toLowerCase();
const matches = list.filter((w) => nameOf(w).toLowerCase() === target);
if (matches.length === 1) {
  return [{ json: { ...base, resolved: { workspace_id: idOf(matches[0]), name: nameOf(matches[0]), matched_by: 'name' } } }];
}

// Кандидати — усе, що ще не закріплене за жодним клієнтом. Показати зайнятий воркспейс означає
// запросити те саме хибне призначення ще раз.
const candidates = list
  .filter((w) => idOf(w) && !claimed.has(idOf(w)))
  .map((w) => ({ workspace_id: idOf(w), name: nameOf(w) || null }));

return [{ json: { ...base, resolved: null, candidates, ambiguous: matches.length > 1 } }];
